test('Galeria: quatro coalizões guardam exatamente 16 cotas canônicas com direitos preservados',function(){
 $f=gfixture();assertSame('16',db()->row("SELECT SUM(balance) n FROM accounts WHERE purpose='galeria_hold'")['n']);assertSame('16',db()->row("SELECT SUM(balance) n FROM accounts WHERE asset='SHARE' AND user_id IS NOT NULL")['n']);foreach($f['all'] as $r){assertSame('2',balance($r['owner'],'SHARE','reserved'));assertSame('0',balance($r['owner'],'SHARE'));}
});
test('Galeria: compra concorrente tem um vencedor e mantém autoridade e histórico',function(){
 $f=gfixture(1);$r=$f['all'][0];[$other]=user('Outro');$offer=op($r['holder'],'galeria.offer',['frame_id'=>$r['frame']['frame_id'],'asset'=>'MR','price'=>'100','expires_at'=>gd('+1 day'),'terms'=>'Revenda após resolver compromissos','confirm'=>true]);
 fail(fn()=>op($other,'galeria.buy',['offer_id'=>$offer['offer_id'],'version'=>$offer['version'],'asset'=>'MR','amount'=>$offer['amount'],'seller_id'=>(string)$r['holder'],'confirm'=>true]));
 ga('event.cancel',['event_id'=>$f['event']['event_id']]);$old=db()->row('SELECT authority_id FROM galeria_frames WHERE id=?',[$r['frame']['frame_id']]);[$third]=user('Terceiro');$calls=[];foreach([$other,$third]as$buyer)$calls[]=['actor'=>$buyer,'action'=>'galeria.buy','data'=>['offer_id'=>$offer['offer_id'],'version'=>$offer['version'],'asset'=>'MR','amount'=>$offer['amount'],'seller_id'=>(string)$r['holder'],'confirm'=>true]];
 $out=concurrent($calls);assertSame(1,count(array_filter($out,fn($x)=>$x['ok'])));assertSame($old['authority_id'],db()->row('SELECT authority_id FROM galeria_frames WHERE id=?',[$r['frame']['frame_id']])['authority_id']);
});
test('Galeria: saldo insuficiente no segundo aceite não cobra parcialmente',function(){
