 $e=db()->row('SELECT * FROM galeria_events');gclock($e['voting_starts']);ga('event.open',['event_id'=>$e['id']]);$c=db()->row('SELECT id FROM galeria_candidates ORDER BY id')['id'];$data=['event_id'=>$e['id'],'candidate_id'=>$c,'confirm'=>true];$out=concurrent([['actor'=>$u,'action'=>'galeria.vote','data'=>$data,'clock'=>$e['voting_starts']],['actor'=>$u,'action'=>'galeria.vote','data'=>$data,'clock'=>$e['voting_starts']]]);assertSame(1,count(array_filter($out,fn($x)=>$x['ok'])));
