test('Galeria: revisão registra nova versão sem revelar parciais ou identidades públicas',function(){
 $f=gfixture();gprepare($f);gvoteFixture($f,[0,0,1]);$q=new Piscina\GaleriaQueries(service());assertSame(null,$q->event((int)$f['event']['event_id'])['result']);gfinish($f,false);$vote=db()->row('SELECT id FROM galeria_votes ORDER BY id LIMIT 1')['id'];ga('vote.invalidate',['event_id'=>$f['event']['event_id'],'vote_id'=>$vote]);assertSame('2',db()->row('SELECT result_version FROM galeria_events')['result_version']);$e=$q->event((int)$f['event']['event_id']);check(!isset($e['votes'])&&!str_contains(json_encode($e),'credential_hash'),'Dados eleitorais não públicos.');
});
test('Galeria: disputa real entre reserva antiga de cotas e aceite novo não gasta duas vezes',function(){
 $f=gfixture(1,false);$r=$f['all'][0];$old=proposal($f['recipient'],$r['holder'],'SHARE','2','0',false);$v=(new Piscina\GaleriaQueries(service()))->proposal($r['holder'],(int)$r['p']['proposal_id'])['versions'][0];
 $out=concurrent([['actor'=>$r['holder'],'action'=>'galeria.accept','data'=>['proposal_id'=>$r['p']['proposal_id'],'version'=>'1','terms_hash'=>$v['terms_hash'],'confirm'=>true,'license_confirm'=>true]],['actor'=>$r['holder'],'action'=>'proposal.approve','data'=>['proposal_id'=>$old['proposal_id'],'version'=>'1']]]);
 assertSame(1,count(array_filter($out,fn($r)=>$r['ok'])));assertSame('0',balance($r['holder'],'SHARE'));assertSame('2',balance($r['holder'],'SHARE','reserved'));
});
test('Galeria: encerrar concorrente com voto fecha um conjunto consistente',function(){
 $f=gfixture();gprepare($f);[$u]=user('UltimoEleitor');ga('event.credential',['event_id'=>$f['event']['event_id'],'user_id'=>(string)$u,'credential_ref'=>'ultima-presenca']);$e=db()->row('SELECT * FROM galeria_events');gclock($e['voting_starts']);ga('event.open',['event_id'=>$e['id']]);$candidate=db()->row('SELECT id FROM galeria_candidates ORDER BY id')['id'];$clock=(new DateTimeImmutable($e['voting_ends'],new DateTimeZone('UTC')))->modify('-2 seconds')->format('Y-m-d H:i:s');
 $out=concurrent([['actor'=>$u,'action'=>'galeria.vote','clock'=>$clock,'data'=>['event_id'=>$e['id'],'candidate_id'=>$candidate,'confirm'=>true]],['actor'=>1,'action'=>'admin.galeria.event.close','clock'=>$e['voting_ends'],'data'=>['event_id'=>$e['id'],'confirm'=>true,'reason'=>'Encerramento em conexão independente']]]);
 check($out[1]['ok'],'Encerramento deve ocorrer.');$actual=db()->row('SELECT COUNT(*) n FROM galeria_votes')['n'];$result=Piscina\GaleriaInput::decode(db()->row('SELECT data FROM galeria_results ORDER BY version DESC LIMIT 1')['data']);assertSame($actual,$result['valid_votes']);assertSame('REVIEW',db()->row('SELECT state FROM galeria_events')['state']);
});
test('Galeria: resíduo em empate vai por ID e depois para parcela da Moldura',function(){
 $f=gfixture(4,true,'1000.01');gprepare($f);gvoteFixture($f,[0,1,2]);gfinish($f);$r=ga('event.settle',['event_id'=>$f['event']['event_id']]);$sum=[];foreach($r['payouts']as$p)$sum[$p['candidate_id']]=bcadd($sum[$p['candidate_id']]??'0',$p['amount'],0);assertSame('100001',$r['paid']);assertSame('33334',array_values($sum)[0]);assertSame('33334',array_values($sum)[1]);assertSame('33333',array_values($sum)[2]);
});
test('Galeria: mídia congelada permanece privada na suspensão e não é apagada pelo cron',function(){
 $f=gfixture();gprepare($f);gvoteFixture($f,[0]);$r=$f['all'][0];$before=db()->row('SELECT * FROM nfts WHERE id=?',[$r['nft']]);$dir=config()['storage'].'/images';$name=bin2hex(random_bytes(16));copy($dir.'/'.$before['image_path'],$dir.'/'.$name.'.jpg');copy($dir.'/'.$before['thumbnail_path'],$dir.'/'.$name.'-thumb.jpg');
 op(1,'admin.nft.image_replace',['nft_id'=>(string)$r['nft'],'image_path'=>$name.'.jpg','thumbnail_path'=>$name.'-thumb.jpg','image_sha'=>hash_file('sha256',$dir.'/'.$name.'.jpg'),'expected_version'=>Piscina\NftImage::editVersion($before),'confirm'=>true,'reason'=>'Atualização durante exposição de teste']);
 assertSame('SUSPENDED',db()->row('SELECT state FROM galeria_events')['state']);$candidate=db()->row('SELECT * FROM galeria_candidates ORDER BY id');$snap=Piscina\GaleriaInput::decode($candidate['snapshot']);assertSame($before['image_path'],$snap['image']['image_path']);touch($dir.'/'.$before['image_path'],time()-172800);(new Piscina\Upload(service(),config()))->cleanup();check(is_file($dir.'/'.$before['image_path']),'Versão histórica preservada.');fail(fn()=>(new Piscina\GaleriaMedia(service()))->file(['candidate_id'=>$candidate['id']],null),404);
 ga('event.cancel',['event_id'=>$f['event']['event_id']]);assertSame('2',balance($r['owner'],'SHARE'));assertSame('100000',db()->row("SELECT balance FROM accounts WHERE code='T:MR:galeria_revenue'")['balance']);
});
test('Galeria: revenda após prestação não muda beneficiários nem créditos do prêmio',function(){
 $f=gfixture();gprepare($f);gvoteFixture($f,[0]);gfinish($f);$r=$f['all'][0];[$buyer]=user('NovoTitular');$o=op($r['holder'],'galeria.offer',['frame_id'=>$r['frame']['frame_id'],'asset'=>'MR','price'=>'0','expires_at'=>gd('+1 day'),'terms'=>'Revenda depois da exposição','confirm'=>true]);op($buyer,'galeria.buy',['offer_id'=>$o['offer_id'],'version'=>$o['version'],'asset'=>'MR','amount'=>$o['amount'],'seller_id'=>(string)$r['holder'],'confirm'=>true]);$old=balance($r['holder'],'MR');$new=balance($buyer,'MR');ga('event.settle',['event_id'=>$f['event']['event_id']]);assertSame('40000',bcsub(balance($r['holder'],'MR'),$old,0));assertSame($new,balance($buyer,'MR'));assertSame($r['holder'],Piscina\GaleriaInput::decode(db()->row('SELECT snapshot FROM galeria_candidates ORDER BY id')['snapshot'])['frame_user']);
});
