 $f=gfixture(1);$r=$f['all'][0];$q=db()->row("SELECT SUM(balance) n FROM accounts WHERE asset='SHARE' AND user_id IS NOT NULL")['n'];period();assertSame($q,db()->row('SELECT total_shares FROM periods ORDER BY id DESC LIMIT 1')['total_shares']);assertSame('2',db()->row('SELECT shares FROM period_snapshots WHERE user_id=? ORDER BY period_id DESC LIMIT 1',[$r['owner']])['shares']);service()->config['galeria']['enabled']=false;op($r['owner'],'galeria.cancel',['agreement_id'=>$r['a']['agreement_id'],'confirm'=>true]);op($r['holder'],'galeria.cancel',['agreement_id'=>$r['a']['agreement_id'],'confirm'=>true]);assertSame('2',balance($r['owner'],'SHARE'));
