test('Galeria: exclusão administrativa encaminha Moldura à custódia e devolve cotas ao fundo',function(){
 $f=gfixture(1);$r=$f['all'][0];op(1,'admin.danger.delete',['user_id'=>(string)$r['holder'],'reason'=>'Encerramento local para testar integração','confirm'=>true,'confirmation'=>'EXCLUIR '.$r['holder']]);assertSame($r['holder'],db()->row('SELECT source_user_id FROM galeria_frame_custody')['source_user_id']);assertSame('SUSPENDED',db()->row('SELECT state FROM galeria_events')['state']);ga('event.cancel',['event_id'=>$f['event']['event_id']]);assertSame('2',db()->row("SELECT balance FROM accounts WHERE user_id=? AND purpose='custody' AND asset='SHARE'",[$r['holder']])['balance']);fail(fn()=>ga('frame.verify',['frame_id'=>$r['frame']['frame_id']]));
