function gtPreview(int $actor,array $d): array {return (new Piscina\MolduraTrades(new Piscina\Galeria(service())))->preview($actor,$d);}
function gtAccept(int $actor,string $id,string $version='1'): array {$p=(new Piscina\MolduraTrades(new Piscina\Galeria(service())))->read($actor,(int)$id);return op($actor,'galeria.trade.accept',['trade_id'=>$id,'version'=>$version,'terms_hash'=>$p['versions'][0]['terms_hash'],'confirm'=>true]);}
test('Galeria: negociação bilateral de revenda aceita contraproposta livre e preserva recibos',function(){
 $f=gfixture(1);$r=$f['all'][0];ga('event.cancel',['event_id'=>$f['event']['event_id']]);$buyer=$f['recipient'];$d=['frame_id'=>$r['frame']['frame_id'],'buyer_id'=>(string)$buyer,'asset'=>'MR','price'=>'33.21','conditions'=>'Direito de operação conforme cadastro','expires_at'=>gd('+1 hour'),'confirm'=>true];$q=gtPreview($buyer,$d);$p=op($buyer,'galeria.trade.propose',$d+['preview_hash'=>$q['preview_hash']]);
 $d['price']='34.56';$d['trade_id']=$p['trade_id'];$d['version']='1';$q=gtPreview($r['holder'],$d);op($r['holder'],'galeria.trade.counter',$d+['preview_hash'=>$q['preview_hash']]);fail(fn()=>gtAccept($buyer,$p['trade_id'],'1'));$before=balance($buyer,'MR');gtAccept($buyer,$p['trade_id'],'2');assertSame('3456',bcsub($before,balance($buyer,'MR'),0));assertSame($buyer,db()->row('SELECT holder_id FROM galeria_frames')['holder_id']);gtAccept($buyer,$p['trade_id'],'2');assertSame(2,db()->row('SELECT COUNT(*) n FROM galeria_sales')['n']);
});
test('Galeria: negociação pendente não cobra e segundo aceite respeita compromissos',function(){
 $f=gfixture(1);$r=$f['all'][0];$buyer=$f['recipient'];$d=['frame_id'=>$r['frame']['frame_id'],'buyer_id'=>(string)$buyer,'asset'=>'MR','price'=>'10','conditions'=>'Interesse de revenda durante exposição','expires_at'=>gd('+1 hour'),'confirm'=>true];$before=balance($buyer,'MR');$q=gtPreview($buyer,$d);$p=op($buyer,'galeria.trade.propose',$d+['preview_hash'=>$q['preview_hash']]);assertSame($before,balance($buyer,'MR'));fail(fn()=>gtAccept($r['holder'],$p['trade_id']));assertSame($before,balance($buyer,'MR'));assertSame('PENDING',db()->row('SELECT state FROM galeria_trade_proposals')['state']);
});
test('Galeria: negociação de Moldura não aceita Admin ou terceiro no lugar da contraparte',function(){
 $f=gfixture(1);$r=$f['all'][0];$d=['frame_id'=>$r['frame']['frame_id'],'buyer_id'=>(string)$f['recipient'],'asset'=>'MR','price'=>'10','conditions'=>'Condições expressas pelas partes','expires_at'=>gd('+1 hour'),'confirm'=>true];$q=gtPreview($f['recipient'],$d);$p=op($f['recipient'],'galeria.trade.propose',$d+['preview_hash'=>$q['preview_hash']]);fail(fn()=>gtAccept($r['owner'],$p['trade_id']),403);fail(fn()=>gtAccept(1,$p['trade_id']),403);assertSame('PENDING',db()->row('SELECT state FROM galeria_trade_proposals')['state']);
});
test('Galeria: ocupação usa horas registradas e preserva o histórico após arquivamento',function(){
 $f=gfixture(1);$r=$f['all'][0];ga('exposure.confirm',['agreement_id'=>$r['a']['agreement_id']]);$a=db()->row('SELECT * FROM galeria_agreements');gclock($a['ends_at']);ga('exposure.complete',['agreement_id'=>$a['id']]);$before=(new Piscina\GaleriaAvailability(new Piscina\Galeria(service())))->read([]);check($before!==null,'Há horas observadas.');assertSame(3600,$before['exhibited_seconds']);check($before['offered_seconds']>=$before['exhibited_seconds'],'Numerador não supera capacidade.');ga('event.cancel',['event_id'=>$f['event']['event_id']]);ga('frame.archive',['frame_id'=>$r['frame']['frame_id']]);$atArchive=(new Piscina\GaleriaAvailability(new Piscina\Galeria(service())))->read([]);gclock(gd('+1 day'));$after=(new Piscina\GaleriaAvailability(new Piscina\Galeria(service())))->read([]);assertSame($atArchive['offered_seconds'],$after['offered_seconds']);assertSame(3600,$after['exhibited_seconds']);
});
