 $f=gfixture();gprepare($f);gvoteFixture($f,[0]);gfinish($f);ga('event.settle',['event_id'=>$f['event']['event_id']]);$before=json_encode(db()->all('SELECT id,balance FROM accounts ORDER BY id'));$v=db()->row('SELECT result_version FROM galeria_events')['result_version'];ga('incident',['event_id'=>$f['event']['event_id'],'reason'=>'Solicitação de conciliação após pagamento']);assertSame($before,json_encode(db()->all('SELECT id,balance FROM accounts ORDER BY id')));assertSame($v,db()->row('SELECT result_version FROM galeria_events')['result_version']);fail(fn()=>ga('event.reopen',['event_id'=>$f['event']['event_id']]));
