 $auth=new Piscina\Auth(db(),config());for($i=0;$i<10;$i++)fail(fn()=>Piscina\GaleriaAdminAuth::check($auth,service(),1,'senha-incorreta'),403);fail(fn()=>Piscina\GaleriaAdminAuth::check($auth,service(),1,'teste-admin-apenas'),429);[$u]=user('NaoAdmin');fail(fn()=>Piscina\GaleriaAdminAuth::check($auth,service(),$u,'senha-local-testes'),403);
