test('Galeria: alteração de local cancela oferta antiga e exige novo consentimento na revenda',function(){
 $f=gfixture(1);$r=$f['all'][0];ga('event.cancel',['event_id'=>$f['event']['event_id']]);$o=op($r['holder'],'galeria.offer',['frame_id'=>$r['frame']['frame_id'],'asset'=>'MR','price'=>'20','expires_at'=>gd('+1 hour'),'terms'=>'Uso conforme autorização original','confirm'=>true]);$d=['frame_id'=>$r['frame']['frame_id'],'buyer_id'=>(string)$f['recipient'],'asset'=>'MR','price'=>'15','conditions'=>'Condições originais do ponto','expires_at'=>gd('+1 hour'),'confirm'=>true];$q=gtPreview($f['recipient'],$d);$p=op($f['recipient'],'galeria.trade.propose',$d+['preview_hash'=>$q['preview_hash']]);$point=db()->row('SELECT * FROM galeria_points ORDER BY id LIMIT 1');$iso=fn($t)=>(new DateTimeImmutable($t,new DateTimeZone('UTC')))->format('Y-m-d\TH:i:s.u\Z');
 ga('point.save',['point_id'=>$point['id'],'space_id'=>$point['space_id'],'name'=>$point['name'],'authorized_from'=>$iso($point['authorized_from']),'authorized_until'=>$iso($point['authorized_until']),'conditions'=>'Novas condições publicadas do espaço']);$before=balance($f['recipient'],'MR');fail(fn()=>gtAccept($r['holder'],$p['trade_id']));assertSame($before,balance($f['recipient'],'MR'));assertSame('CANCELLED',db()->row('SELECT state FROM galeria_offers WHERE id=?',[$o['offer_id']])['state']);
});
